import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Search the literature","description":"","frontmatter":{},"headers":[],"relativePath":"guide/search.md","filePath":"guide/search.md","lastUpdated":1793111003000}'),n={name:"guide/search.md"};function s(i,e,d,c,h,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="search-the-literature" tabindex="-1">Search the literature <a class="header-anchor" href="#search-the-literature" aria-label="Permalink to &quot;Search the literature&quot;">​</a></h1><p>Describe what you want to understand. PaperSeek prepares source-specific queries and shows how the search develops.</p><h2 id="workspace-navigation" tabindex="-1">Workspace navigation <a class="header-anchor" href="#workspace-navigation" aria-label="Permalink to &quot;Workspace navigation&quot;">​</a></h2><p>Search settings, Run progress, and Results are separate views within Search. Model defaults live in the standalone settings page, opened from the sidebar footer; source, scope, and budget remain in the draft. Stop is available in the run header across views. Switching views does not restart the run.</p><h2 id="write-a-focused-question" tabindex="-1">Write a focused question <a class="header-anchor" href="#write-a-focused-question" aria-label="Permalink to &quot;Write a focused question&quot;">​</a></h2><p>Name the subject and relationship you care about. Add a method, population, period, or context when essential.</p><p><strong>Broad:</strong> “Open-source software.”<br><strong>Focused:</strong> “How do funding mechanisms affect the long-term maintenance of open-source software?”</p><p>Use English or Chinese natural language; no hand-written Boolean query is required. The question field accepts up to 10,000 characters.</p><h2 id="choose-the-source-and-scope" tabindex="-1">Choose the source and scope <a class="header-anchor" href="#choose-the-source-and-scope" aria-label="Permalink to &quot;Choose the source and scope&quot;">​</a></h2><p>A run starts from <strong>one selected source</strong>. Multiple retrieval paths do not mean that all eleven sources are queried in the same run.</p><p>OpenAlex, arXiv, and WoS offer source-specific field filters. Other sources use a research-field hint while planning queries. A hint is not a database-level hard filter.</p><p>OpenAlex citation expansion adds references and citing works within a budget. It introduces additional requests and can take longer.</p><h2 id="set-a-budget" tabindex="-1">Set a budget <a class="header-anchor" href="#set-a-budget" aria-label="Permalink to &quot;Set a budget&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Interface</th><th>API / CLI</th><th>Use</th></tr></thead><tbody><tr><td>Auto</td><td>—</td><td>Let PaperSeek choose the search budget</td></tr><tr><td>Fast</td><td><code>fast</code></td><td>Smaller retrieval and scoring budget</td></tr><tr><td>Balanced</td><td><code>medium</code></td><td>Broader coverage and ranking</td></tr><tr><td>Deep</td><td><code>high</code></td><td>More candidates and citation exploration</td></tr><tr><td>Maximum</td><td><code>max</code></td><td>Largest bounded search budget</td></tr></tbody></table><p>These are work limits, not promises of a paper count or completion time. Larger budgets can increase latency and cost. A focused question may help more than choosing Maximum.</p><h2 id="follow-the-four-stages" tabindex="-1">Follow the four stages <a class="header-anchor" href="#follow-the-four-stages" aria-label="Permalink to &quot;Follow the four stages&quot;">​</a></h2><ol><li><strong>Intent and queries:</strong> understand the scope and prepare the strategy.</li><li><strong>Query iteration:</strong> test and refine queries using source feedback.</li><li><strong>Retrieval and ranking:</strong> collect candidates, optionally expand citations, apply preliminary ranking, and evaluate relevance. The model scores the candidates in batches of 64 and then writes a “Why it ranks” reason for every well-scoring paper in groups of 32; up to eight batches or groups run at once, and each has its own progress row.</li><li><strong>Results:</strong> prepare the reading list and exports.</li></ol><p>The UI shows stage status and details, rather than a raw terminal log.</p><h3 id="understand-the-counts" tabindex="-1">Understand the counts <a class="header-anchor" href="#understand-the-counts" aria-label="Permalink to &quot;Understand the counts&quot;">​</a></h3><p>A source may report thousands of hits while only one page has been downloaded. <strong>Source hits</strong>, <strong>retrieved candidates</strong>, and <strong>final results</strong> describe different sets.</p><p>PaperSeek can narrow an overly broad query before fetching a candidate pool. Repeated or unproductive rewrites stop, and selection can return to a better recorded query rather than automatically using the last rewrite. Candidate pools remain bounded; the output is not an exhaustive corpus.</p><h2 id="stop-or-reconnect" tabindex="-1">Stop or reconnect <a class="header-anchor" href="#stop-or-reconnect" aria-label="Permalink to &quot;Stop or reconnect&quot;">​</a></h2><p>Use <strong>Stop</strong> to request cancellation. <strong>Cancelling</strong> can remain briefly while in-flight work finishes.</p><p>Refreshing a persisted run reconnects to saved state. A network reconnect is not a new search. Retrying a finished or cancelled run starts new work; it does not reopen the old execution.</p><p>Online queueing is covered in the <a href="./../online/#when-your-task-is-queued">online overview</a>; anonymous sessions in <a href="./../online/privacy#search-without-signing-in">Data &amp; privacy</a>.</p>',25)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
